contents: dict[str, str] = {}
for path, old, _new in REPLACEMENTS:
    contents.setdefault(path, Path(path).read_text(encoding="utf-8"))
    count = contents[path].count(old)
    if count != 1:
        raise SystemExit(f"{path}: expected one marker, found {count}")

for path, old, new in REPLACEMENTS:
    current = contents[path]
    contents[path] = current.replace(old, new, 1)

for path, text in contents.items():
    Path(path).write_text(text, encoding="utf-8")
